const deals = $('Listar Deals').all().flatMap(item => item.json.results || []);

function getAssociationIds(record, associationType) {
  return (record.associations?.[associationType]?.results || []).map(item => item.id);
}

function chunkArray(arr, size = 100) {
  const chunks = [];
  for (let i = 0; i < arr.length; i += size) {
    chunks.push(arr.slice(i, i + size));
  }
  return chunks;
}

const allContactIds = deals.flatMap(deal => getAssociationIds(deal, 'contacts'));
const uniqueIds = [...new Set(allContactIds.map(String))];

if (!uniqueIds.length) {
  return [{ json: { skip: true, type: 'contacts', body: { properties: ['firstname', 'lastname', 'email', 'phone', 'company'], inputs: [] } } }];
}

return chunkArray(uniqueIds, 100).map(chunk => ({
  json: {
    skip: false,
    type: 'contacts',
    body: {
      properties: ['firstname', 'lastname', 'email', 'phone', 'company'],
      inputs: chunk.map(id => ({ id }))
    }
  }
}));

